 if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';elseif(!verify_admin_password($conn,$_SESSION['admin_id'],$_POST['admin_password']??''))$error='Correct administrator password is required.';else{$username=trim($_POST['username']??'');$name=trim($_POST['full_name']??'');$password=trim($_POST['password']??'');if($password==='')$password=substr(strtoupper(bin2hex(random_bytes(6))),0,10);if(!preg_match('/^[A-Za-z0-9_.-]{3,80}$/',$username))$error='Username must contain 3–80 letters, numbers, dots, dashes, or underscores.';elseif($name==='')$error='Complete name is required.';elseif(strlen($password)<8)$error='Password must contain at least 8 characters.';else{$r=pg_query_params($conn,"INSERT INTO admins(username,password_hash,full_name,role) VALUES($1,$2,$3,'marshal') RETURNING id",[$username,password_hash($password,PASSWORD_DEFAULT),$name]);if($r){$_SESSION['issued_marshal']=['username'=>$username,'password'=>$password,'name'=>$name];audit_log($conn,'marshal_created','admin',pg_fetch_result($r,0,0));redirect('index.php');}$error='That marshal username is already in use.';}}
